{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://clawhub.dev/schemas/taskflow/export-projects-overview/v1",
  "title": "TaskFlow Export — Projects Overview",
  "description": "Output schema for scripts/export-projects-overview.mjs (taskflow-009). Emitted to stdout as a single JSON object.",
  "type": "object",
  "required": ["exported_at", "projects", "recent_transitions"],
  "additionalProperties": false,
  "properties": {

    "exported_at": {
      "type": "string",
      "format": "date-time",
      "description": "ISO 8601 timestamp when the export was generated (UTC)."
    },

    "projects": {
      "type": "array",
      "description": "All projects in the TaskFlow DB, ordered by slug.",
      "items": {
        "type": "object",
        "required": ["id", "name", "description", "status", "task_counts", "progress_pct"],
        "additionalProperties": false,
        "properties": {

          "id": {
            "type": "string",
            "description": "Project slug — primary key in the `projects` table.",
            "examples": ["dashboard", "trading", "smart-home"]
          },

          "name": {
            "type": "string",
            "description": "Human-readable project name.",
            "examples": ["Dashboard", "Trading System"]
          },

          "description": {
            "type": "string",
            "description": "One-liner description (may be empty string)."
          },

          "status": {
            "type": "string",
            "enum": ["active", "paused", "done"],
            "description": "Project lifecycle status."
          },

          "task_counts": {
            "type": "object",
            "description": "Count of tasks in each status bucket for this project.",
            "required": ["in_progress", "pending_validation", "backlog", "blocked", "done"],
            "additionalProperties": false,
            "properties": {
              "in_progress":        { "type": "integer", "minimum": 0 },
              "pending_validation": { "type": "integer", "minimum": 0 },
              "backlog":            { "type": "integer", "minimum": 0 },
              "blocked":            { "type": "integer", "minimum": 0 },
              "done":               { "type": "integer", "minimum": 0 }
            }
          },

          "progress_pct": {
            "type": "number",
            "minimum": 0,
            "maximum": 100,
            "description": "Completion percentage: done / total * 100, rounded to 2 decimal places. 0 when there are no tasks."
          }

        }
      }
    },

    "recent_transitions": {
      "type": "array",
      "description": "Last 20 task status transitions across all projects, ordered oldest-first within the window. Sourced from task_transitions_v2.",
      "maxItems": 20,
      "items": {
        "type": "object",
        "required": ["task_id", "to_status", "at"],
        "additionalProperties": false,
        "properties": {

          "task_id": {
            "type": "string",
            "description": "Task identifier in <slug>-NNN format.",
            "examples": ["dashboard-025", "trading-003"]
          },

          "from_status": {
            "type": ["string", "null"],
            "enum": ["backlog", "in_progress", "pending_validation", "blocked", "done", null],
            "description": "Previous status. Null for task creation events."
          },

          "to_status": {
            "type": "string",
            "enum": ["backlog", "in_progress", "pending_validation", "blocked", "done"],
            "description": "Status the task transitioned into."
          },

          "reason": {
            "type": ["string", "null"],
            "description": "Optional free-text reason recorded at transition time."
          },

          "at": {
            "type": "string",
            "format": "date-time",
            "description": "ISO 8601 timestamp of the transition (UTC)."
          }

        }
      }
    }

  }
}

{
  "name": "@taskflow/core",
  "version": "0.1.0",
  "description": "TaskFlow — ClawHub skill for structured project/task management with markdown-first authoring and SQLite-backed querying.",
  "license": "MIT",
  "type": "module",
  "engines": {
    "node": ">=22.5"
  },
  "scripts": {
    "init-db": "node scripts/init-db.mjs",
    "sync": "node scripts/task-sync.mjs files-to-db",
    "export": "node scripts/export-projects-overview.mjs",
    "status": "node bin/taskflow status"
  },
  "dependencies": {},
  "devDependencies": {}
}

#!/usr/bin/env node
/**
 * apple-notes-export.mjs (taskflow-012)
 *
 * Generates an HTML project-status summary from TaskFlow markdown files and
 * writes it to an Apple Note via osascript.
 *
 * Config: $OPENCLAW_WORKSPACE/taskflow.config.json
 *   {
 *     "appleNotesId":     "x-coredata://...",   // persisted after first run
 *     "appleNotesFolder": "Notes",               // Notes folder name
 *     "appleNotesTitle":  "TaskFlow - Project Status"
 *   }
 *
 * Usage:
 *   node scripts/apple-notes-export.mjs
 *   taskflow notes
 *
 * macOS only — exits gracefully on other platforms.
 */

import { existsSync, readFileSync, writeFileSync, readdirSync } from 'node:fs'
import { execSync } from 'node:child_process'
import path from 'node:path'

// ── Platform guard ─────────────────────────────────────────────────────────
if (process.platform !== 'darwin') {
  console.log('[apple-notes-export] Skipping: Apple Notes sync is macOS only.')
  process.exit(0)
}

// ── Paths ──────────────────────────────────────────────────────────────────
const workspace  = process.env.OPENCLAW_WORKSPACE || process.cwd()
const configPath = path.join(workspace, 'taskflow.config.json')
const tasksDir   = path.join(workspace, 'tasks')
const projectsFile = path.join(workspace, 'PROJECTS.md')

// ── Config helpers ─────────────────────────────────────────────────────────

/**
 * Read taskflow.config.json (returns {} if missing or unparseable).
 */
function readConfig() {
  if (!existsSync(configPath)) return {}
  try {
    return JSON.parse(readFileSync(configPath, 'utf8'))
  } catch {
    return {}
  }
}

/**
 * Merge `updates` into taskflow.config.json (non-destructive patch).
 */
function writeConfig(updates) {
  const current = readConfig()
  const merged  = { ...current, ...updates }
  writeFileSync(configPath, JSON.stringify(merged, null, 2) + '\n', 'utf8')
}

// ── Parse PROJECTS.md ──────────────────────────────────────────────────────

function parseProjects() {
  if (!existsSync(projectsFile)) return {}
  const lines = readFileSync(projectsFile, 'utf8').split('\n')
  const projects = {}
  let currentSlug = null

  for (const line of lines) {
    const h2 = line.match(/^## (.+)/)
    if (h2) {
      currentSlug = h2[1].trim()
      projects[currentSlug] = { name: currentSlug, desc: '' }
      continue
    }
    if (!currentSlug) continue
    const nameMatch = line.match(/^- Name: (.+)/)
    if (nameMatch) { projects[currentSlug].name = nameMatch[1].trim(); continue }
    const descMatch = line.match(/^- Description: (.+)/)
    if (descMatch) { projects[currentSlug].desc = descMatch[1].trim() }
  }
  return projects
}

// ── Parse task files ───────────────────────────────────────────────────────

function parseTasks(projects) {
  const result = { in_progress: [], pending: [], backlog: [], done: [], blocked: [] }

  if (!existsSync(tasksDir)) return result

  const files = readdirSync(tasksDir)
    .filter(f => f.endsWith('-tasks.md'))
    .sort()

  for (const file of files) {
    const slug     = file.replace('-tasks.md', '')
    const projName = projects[slug]?.name ?? slug
    const lines    = readFileSync(path.join(tasksDir, file), 'utf8').split('\n')

    let section = null
    for (const line of lines) {
      const trimmed = line.trim()
      if (trimmed.startsWith('## ')) {
        const h = trimmed.slice(3).toLowerCase()
        if (h.includes('in progress'))  section = 'in_progress'
        else if (h.includes('pending')) section = 'pending'
        else if (h.includes('backlog')) section = 'backlog'
        else if (h.includes('done'))    section = 'done'
        else if (h.includes('blocked')) section = 'blocked'
        else section = null
        continue
      }
      if (!trimmed.startsWith('- [') || section === null) continue

      // Strip checkbox, task ID, priority/owner tags
      let text = trimmed
        .replace(/^- \[.\]\s*/, '')
        .replace(/\(task:\S+\)\s*/g, '')
        .replace(/\[P\d\]\s*/g, '')
        .replace(/\[\S+\]\s*/g, '')
        .trim()
      if (!text) continue

      result[section].push(`${projName}: ${text}`)
    }
  }
  return result
}

// ── HTML generation ────────────────────────────────────────────────────────

function escapeHtml(str) {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

function ul(items) {
  if (!items || items.length === 0) {
    return '<ul><li><span style="color:#666;">None</span></li></ul>'
  }
  return '<ul>' + items.map(i => `<li>${escapeHtml(i)}</li>`).join('') + '</ul>'
}

function generateHtml(tasks, title) {
  const { in_progress, pending, backlog, done, blocked } = tasks
  const top   = [...in_progress, ...pending].slice(0, 5)
  const next3 = in_progress.length > 0 ? in_progress.slice(0, 3) : backlog.slice(0, 3)

  const now = new Date()
  const stamp = now.toLocaleString('en-US', {
    timeZone: 'America/Chicago',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: true,
  }) + ' CST'

  return `<div style="font-family:-apple-system,Helvetica,Arial,sans-serif; line-height:1.35;">
<h1>${escapeHtml(title)}</h1>
<h2>🎯 Top Priorities</h2>${ul(top)}
<h2>🚧 In Progress (${in_progress.length})</h2>${ul(in_progress)}
<h2>⏳ Pending Validation (${pending.length})</h2>${ul(pending)}
<h2>📥 Backlog (top 12)</h2>${ul(backlog.slice(0, 12))}
<h2>✅ Recently Done</h2>${ul(done.slice(0, 10))}
<h2>🧱 Blockers</h2>${ul(blocked)}
<h2>▶️ Next 3 Actions</h2>${ul(next3)}
<p style="color:#888; font-size:0.85em;"><b>Updated:</b> ${escapeHtml(stamp)} &middot; Source: tasks/*.md</p>
</div>`
}

// ── AppleScript helpers ────────────────────────────────────────────────────

/**
 * Escape a string for embedding inside an AppleScript string literal.
 */
function asEscape(str) {
  // In AppleScript, backslash and double-quote need to be escaped for shell
  // We'll write HTML to a temp file and read it in AppleScript to avoid quoting issues.
  return str
}

const TMP_HTML = '/tmp/taskflow-apple-notes.html'

/**
 * Check whether a note with the given Core Data ID exists.
 * Returns true/false.
 */
function noteExists(noteId) {
  const script = `
tell application "Notes"
  try
    set n to note id "${noteId}"
    return (name of n) as text
  on error
    return "NOT_FOUND"
  end try
end tell
`
  try {
    const result = execSync(`/usr/bin/osascript -e '${script.replace(/'/g, "'\\''")}'`, {
      encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe']
    }).trim()
    return result !== 'NOT_FOUND'
  } catch {
    return false
  }
}

/**
 * Update an existing note by Core Data ID.
 */
function updateNote(noteId, title, html) {
  writeFileSync(TMP_HTML, html, 'utf8')
  const script = `
set noteBody to (do shell script "cat /tmp/taskflow-apple-notes.html")
tell application "Notes"
  try
    set targetNote to note id "${noteId}"
    set name of targetNote to "${title.replace(/"/g, '\\"')}"
    set body of targetNote to noteBody
    return (id of targetNote) as text
  on error errMsg
    error errMsg
  end try
end tell
`
  const result = execSync(`/usr/bin/osascript << 'OSASCRIPT'\n${script}\nOSASCRIPT`, {
    encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe']
  }).trim()
  return result
}

/**
 * Create a new note in the specified folder.
 * Returns the new note's Core Data ID.
 */
function createNote(title, html, folder) {
  writeFileSync(TMP_HTML, html, 'utf8')
  const script = `
set noteBody to (do shell script "cat /tmp/taskflow-apple-notes.html")
tell application "Notes"
  launch
  delay 0.5
  set targetFolder to missing value
  try
    set targetFolder to folder "${folder.replace(/"/g, '\\"')}"
  on error
    -- folder not found, use default account
  end try
  if targetFolder is missing value then
    set newNote to make new note with properties {name:"${title.replace(/"/g, '\\"')}", body:noteBody}
  else
    set newNote to make new note at targetFolder with properties {name:"${title.replace(/"/g, '\\"')}", body:noteBody}
  end if
  return (id of newNote) as text
end tell
`
  const result = execSync(`/usr/bin/osascript << 'OSASCRIPT'\n${script}\nOSASCRIPT`, {
    encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe']
  }).trim()
  return result
}

// ── Main ───────────────────────────────────────────────────────────────────

async function main() {
  const config = readConfig()
  const folder = config.appleNotesFolder ?? 'Notes'
  const title  = config.appleNotesTitle  ?? 'TaskFlow - Project Status'
  let   noteId = config.appleNotesId     ?? null

  // Parse content
  const projects = parseProjects()
  const tasks    = parseTasks(projects)
  const html     = generateHtml(tasks, title)

  const { in_progress, pending, backlog, done, blocked } = tasks
  console.log(`[apple-notes-export] ${in_progress.length} in-progress, ${backlog.length} backlog, ${done.length} done`)

  // Retry loop (up to 3 attempts)
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      if (noteId && noteExists(noteId)) {
        // Update existing note
        console.log(`[apple-notes-export] Updating existing note…`)
        updateNote(noteId, title, html)
        console.log(`[apple-notes-export] ✓ Note updated (${noteId})`)
        break
      } else {
        // Create new note (either no ID configured, or note was deleted)
        if (noteId) {
          console.log(`[apple-notes-export] Previous note not found — creating new note…`)
        } else {
          console.log(`[apple-notes-export] No note configured — creating new note in "${folder}"…`)
        }
        const newId = createNote(title, html, folder)
        if (!newId) throw new Error('osascript returned empty note ID')

        noteId = newId
        writeConfig({
          appleNotesId:     noteId,
          appleNotesFolder: folder,
          appleNotesTitle:  title,
        })
        console.log(`[apple-notes-export] ✓ Note created and ID saved to taskflow.config.json`)
        console.log(`[apple-notes-export]   ID: ${noteId}`)
        break
      }
    } catch (err) {
      console.error(`[apple-notes-export] Attempt ${attempt} failed: ${err.message}`)
      if (attempt < 3) {
        await new Promise(r => setTimeout(r, 2000))
      } else {
        console.error('[apple-notes-export] All retries exhausted. Note not updated.')
        process.exit(1)
      }
    }
  }
}

await main()

#!/usr/bin/env node
/**
 * export-projects-overview.mjs (taskflow-009)
 * 
 * Reads the TaskFlow SQLite DB and emits a clean JSON summary to stdout.
 * 
 * Output shape:
 *   {
 *     exported_at: ISO string,
 *     projects: [ { id, name, description, status, task_counts, progress_pct } ],
 *     recent_transitions: [ { task_id, from_status, to_status, reason, at } ]
 *   }
 * 
 * Usage:
 *   node scripts/export-projects-overview.mjs
 *   node scripts/export-projects-overview.mjs | jq .
 */

import { DatabaseSync } from 'node:sqlite'
import path from 'node:path'
import { existsSync } from 'node:fs'

// ── DB path resolution ─────────────────────────────────────────────────────
const workspace = process.env.OPENCLAW_WORKSPACE || process.cwd()
const dbPath = path.join(workspace, 'memory', 'taskflow.sqlite')

if (!existsSync(dbPath)) {
  process.stderr.write(
    `[taskflow-export] DB not found at: ${dbPath}\n` +
    `  Run 'taskflow init' to bootstrap the database.\n`
  )
  process.exit(1)
}

const db = new DatabaseSync(dbPath)
db.exec('PRAGMA foreign_keys = ON')
db.exec('PRAGMA journal_mode = WAL')

// ── Fetch projects ─────────────────────────────────────────────────────────
const projects = db
  .prepare('SELECT id, name, description, status FROM projects ORDER BY id')
  .all()

// ── Task counts per project ────────────────────────────────────────────────
const ALL_STATUSES = ['in_progress', 'pending_validation', 'backlog', 'blocked', 'done']

const countRows = db
  .prepare(`
    SELECT project_id, status, COUNT(*) AS cnt
    FROM tasks_v2
    GROUP BY project_id, status
  `)
  .all()

// Build lookup: { project_id: { status: count } }
const countsByProject = {}
for (const row of countRows) {
  if (!countsByProject[row.project_id]) countsByProject[row.project_id] = {}
  countsByProject[row.project_id][row.status] = row.cnt
}

// ── Assemble project objects ───────────────────────────────────────────────
const projectsOut = projects.map((p) => {
  const counts = countsByProject[p.id] || {}

  const task_counts = {
    in_progress:         counts.in_progress         ?? 0,
    pending_validation:  counts.pending_validation  ?? 0,
    backlog:             counts.backlog              ?? 0,
    blocked:             counts.blocked              ?? 0,
    done:                counts.done                ?? 0,
  }

  const total = Object.values(task_counts).reduce((s, n) => s + n, 0)
  const progress_pct = total > 0
    ? Math.round((task_counts.done / total) * 10000) / 100   // 2 decimal places
    : 0

  return {
    id:           p.id,
    name:         p.name,
    description:  p.description,
    status:       p.status,
    task_counts,
    progress_pct,
  }
})

// ── Recent transitions (last 20) ───────────────────────────────────────────
const recentTransitions = db
  .prepare(`
    SELECT task_id, from_status, to_status, reason, at
    FROM task_transitions_v2
    ORDER BY id DESC
    LIMIT 20
  `)
  .all()

// Reverse so oldest-first within the window (more natural for consumers)
recentTransitions.reverse()

// ── Output ─────────────────────────────────────────────────────────────────
const output = {
  exported_at:         new Date().toISOString(),
  projects:            projectsOut,
  recent_transitions:  recentTransitions,
}

process.stdout.write(JSON.stringify(output, null, 2) + '\n')

#!/usr/bin/env node
/**
 * init-db.mjs — TaskFlow SQLite bootstrap (idempotent)
 *
 * Reads schema/taskflow.sql and executes it against the TaskFlow SQLite DB.
 * Safe to run multiple times — all DDL uses IF NOT EXISTS.
 *
 * DB path resolution (in order):
 *   1. $OPENCLAW_WORKSPACE/memory/taskflow.sqlite
 *   2. process.cwd()/memory/taskflow.sqlite
 *
 * Usage:
 *   node scripts/init-db.mjs
 *   npm run init-db
 *
 * Requires: Node >=22.5 (node:sqlite / DatabaseSync)
 */

import { DatabaseSync } from 'node:sqlite';
import { readFileSync, mkdirSync, existsSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

// ---------------------------------------------------------------------------
// Resolve paths
// ---------------------------------------------------------------------------

const __dirname = dirname(fileURLToPath(import.meta.url));
const schemaPath = resolve(__dirname, '..', 'schema', 'taskflow.sql');

const workspaceRoot = process.env.OPENCLAW_WORKSPACE
  ? process.env.OPENCLAW_WORKSPACE
  : process.cwd();

const memoryDir = join(workspaceRoot, 'memory');
const dbPath = join(memoryDir, 'taskflow.sqlite');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function log(msg) {
  const ts = new Date().toISOString();
  console.log(`[${ts}] ${msg}`);
}

function err(msg) {
  const ts = new Date().toISOString();
  console.error(`[${ts}] ERROR: ${msg}`);
}

/**
 * Split a SQL file into individual statements, stripping comments and blanks.
 * Handles multi-line statements and PRAGMA directives.
 */
function splitStatements(sql) {
  // Remove -- line comments
  const stripped = sql.replace(/--[^\n]*/g, '');
  // Split on semicolons, filter blank/whitespace-only entries
  return stripped
    .split(';')
    .map(s => s.trim())
    .filter(s => s.length > 0);
}

/**
 * Detect the statement type for human-readable logging.
 */
function describeStatement(stmt) {
  const upper = stmt.trimStart().toUpperCase();
  if (upper.startsWith('CREATE TABLE IF NOT EXISTS')) {
    const m = stmt.match(/CREATE TABLE IF NOT EXISTS\s+(\S+)/i);
    return m ? `CREATE TABLE IF NOT EXISTS ${m[1]}` : 'CREATE TABLE (IF NOT EXISTS)';
  }
  if (upper.startsWith('CREATE INDEX IF NOT EXISTS')) {
    const m = stmt.match(/CREATE INDEX IF NOT EXISTS\s+(\S+)/i);
    return m ? `CREATE INDEX IF NOT EXISTS ${m[1]}` : 'CREATE INDEX (IF NOT EXISTS)';
  }
  if (upper.startsWith('CREATE')) {
    return stmt.trimStart().split(/\s+/).slice(0, 4).join(' ');
  }
  if (upper.startsWith('INSERT OR IGNORE')) {
    const m = stmt.match(/INTO\s+(\S+)/i);
    return m ? `INSERT OR IGNORE INTO ${m[1]}` : 'INSERT OR IGNORE';
  }
  if (upper.startsWith('PRAGMA')) {
    return stmt.trimStart().split('\n')[0].trim();
  }
  return stmt.trimStart().split(/\s+/).slice(0, 3).join(' ');
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

log('TaskFlow init-db starting');
log(`Schema: ${schemaPath}`);
log(`DB:     ${dbPath}`);

// Ensure memory directory exists
if (!existsSync(memoryDir)) {
  mkdirSync(memoryDir, { recursive: true });
  log(`Created directory: ${memoryDir}`);
} else {
  log(`Directory exists:  ${memoryDir}`);
}

// Read schema
let schemaSQL;
try {
  schemaSQL = readFileSync(schemaPath, 'utf8');
} catch (e) {
  err(`Cannot read schema file: ${schemaPath}\n${e.message}`);
  process.exit(1);
}

// Open (or create) DB
let db;
try {
  db = new DatabaseSync(dbPath);
  log(`Opened DB (created if new): ${dbPath}`);
} catch (e) {
  err(`Cannot open SQLite DB at ${dbPath}\n${e.message}`);
  process.exit(1);
}

// Execute each statement
const statements = splitStatements(schemaSQL);
log(`Executing ${statements.length} SQL statement(s)...`);
console.log('');

let ok = 0;
let skipped = 0;

for (const stmt of statements) {
  const label = describeStatement(stmt);
  try {
    db.exec(stmt);
    log(`  ✓  ${label}`);
    ok++;
  } catch (e) {
    // PRAGMA errors on read-only pragmas are non-fatal; everything else is fatal.
    if (stmt.trim().toUpperCase().startsWith('PRAGMA')) {
      log(`  ~  ${label} (skipped — ${e.message})`);
      skipped++;
    } else {
      err(`Failed: ${label}\n       ${e.message}`);
      db.close?.();
      process.exit(1);
    }
  }
}

// Verify expected tables exist
const EXPECTED_TABLES = [
  'projects',
  'tasks_v2',
  'task_transitions_v2',
  'sync_state',
  'legacy_key_map',
];

console.log('');
log('Verifying tables...');

const tableRows = db
  .prepare("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
  .all();
const existingTables = new Set(tableRows.map(r => r.name));

let allPresent = true;
for (const t of EXPECTED_TABLES) {
  if (existingTables.has(t)) {
    log(`  ✓  table: ${t}`);
  } else {
    log(`  ✗  MISSING table: ${t}`);
    allPresent = false;
  }
}

// Verify singleton sync_state row
const syncRow = db.prepare('SELECT id FROM sync_state WHERE id = 1').get();
if (syncRow) {
  log(`  ✓  sync_state singleton row present`);
} else {
  log(`  ✗  sync_state singleton row MISSING`);
  allPresent = false;
}

// Summary
console.log('');
if (allPresent) {
  log(`init-db complete — ${ok} statement(s) executed, ${skipped} skipped`);
  log(`TaskFlow DB is ready at: ${dbPath}`);
} else {
  err('init-db completed with warnings — some expected tables are missing');
  process.exit(1);
}

#!/usr/bin/env node
/**
 * task-sync.mjs -- Sync task markdown files to/from SQLite
 *
 * Usage:
 *   node scripts/task-sync.mjs files-to-db     # parse markdown, update DB
 *   node scripts/task-sync.mjs check            # detect drift, exit 1 if mismatch
 *   node scripts/task-sync.mjs db-to-files      # project DB state into markdown
 *
 * Environment:
 *   OPENCLAW_WORKSPACE  Path to the workspace root (defaults to process.cwd())
 */
import { DatabaseSync } from 'node:sqlite'
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs'
import path from 'node:path'
import { createHash } from 'node:crypto'

// === PATHS (taskflow-001: portable, no hardcoded paths) ===
const workspace = process.env.OPENCLAW_WORKSPACE || process.cwd()
const dbPath    = path.join(workspace, 'memory', 'taskflow.sqlite')
const tasksDir  = path.join(workspace, 'tasks')

const mode = process.argv[2] || 'check'
if (!['files-to-db', 'check', 'db-to-files'].includes(mode)) {
  console.error('Usage: node scripts/task-sync.mjs [files-to-db|check|db-to-files]')
  process.exit(1)
}

// === STARTUP CHECKS (taskflow-020: clear errors for missing paths) ===
if (!existsSync(workspace)) {
  console.error(`ERROR: Workspace directory not found: ${workspace}`)
  console.error('Set OPENCLAW_WORKSPACE to your workspace root and try again.')
  process.exit(1)
}
if (!existsSync(tasksDir)) {
  console.error(`ERROR: Tasks directory not found: ${tasksDir}`)
  console.error(`Create it with: mkdir -p "${tasksDir}"`)
  process.exit(1)
}
if (!existsSync(dbPath)) {
  console.error(`ERROR: Database file not found: ${dbPath}`)
  console.error('Run init-db.mjs first to create the database schema.')
  process.exit(1)
}

const db = new DatabaseSync(dbPath)
db.exec('PRAGMA foreign_keys = ON')

// === LOCK (taskflow-002: atomic single-UPDATE acquisition) ===
let lockAcquired = false

function acquireLock() {
  const owner = `task-sync:${mode}`
  const until = new Date(Date.now() + 60_000).toISOString() // 60s TTL

  // Ensure the singleton row exists
  db.exec(`INSERT OR IGNORE INTO sync_state (id, lock_owner, lock_until) VALUES (1, NULL, NULL)`)

  // Single atomic UPDATE: succeeds only when no valid lock is held
  const result = db.prepare(`
    UPDATE sync_state
    SET lock_owner = ?, lock_until = ?
    WHERE id = 1
      AND (lock_owner IS NULL OR lock_until < datetime('now'))
  `).run(owner, until)

  if (result.changes === 0) {
    const row = db.prepare('SELECT lock_owner, lock_until FROM sync_state WHERE id = 1').get()
    console.error(`Sync locked by ${row?.lock_owner} until ${row?.lock_until}`)
    process.exit(1)
  }

  lockAcquired = true
}

function releaseLock(result) {
  const now = new Date().toISOString()
  db.prepare(
    'UPDATE sync_state SET lock_owner = NULL, lock_until = NULL, last_sync_at = ?, last_result = ? WHERE id = 1'
  ).run(now, result)
  lockAcquired = false
}

// === SIGNAL HANDLERS (taskflow-019: release lock on exit) ===
function handleSignal(signal) {
  if (lockAcquired) {
    try { releaseLock(`interrupted: ${signal}`) } catch (_) {}
  }
  process.exit(signal === 'SIGTERM' ? 0 : 130)
}
process.on('SIGTERM', () => handleSignal('SIGTERM'))
process.on('SIGINT',  () => handleSignal('SIGINT'))

// === PARSE MARKDOWN ===
const STATUS_MAP = {
  'in progress':        'in_progress',
  'pending validation': 'pending_validation',
  'backlog':            'backlog',
  'done':               'done',
  'blocked':            'blocked',
}

const TASK_RE = /^- \[([ x])\] \(task:([a-z0-9-]+)\)\s*(?:\[([^\]]*)\])?\s*(?:\[([^\]]*)\])?\s*(.+)$/

function parseTaskFile(filePath) {
  const content = readFileSync(filePath, 'utf8')
  const lines   = content.split(/\r?\n/)
  const tasks   = []
  let currentStatus = null
  const slug = path.basename(filePath).replace(/-tasks\.md$/, '')

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]

    // Section header
    const headerMatch = line.match(/^## (.+)$/)
    if (headerMatch) {
      const normalized = headerMatch[1].trim().toLowerCase()
      currentStatus = STATUS_MAP[normalized] || null
      continue
    }

    if (!currentStatus) continue

    const taskMatch = line.match(TASK_RE)
    if (taskMatch) {
      const [, , id, tag1, tag2, title] = taskMatch

      // Parse priority and model from tags
      let priority = 'P2', model = null
      for (const tag of [tag1, tag2]) {
        if (!tag) continue
        if (/^P\d$/.test(tag)) priority = tag
        else model = tag
      }

      // Check for note on next line
      let notes = null
      if (i + 1 < lines.length) {
        const noteMatch = lines[i + 1].match(/^\s+- note:\s*(.+)$/)
        if (noteMatch) notes = noteMatch[1].trim()
      }

      tasks.push({
        id,
        project_id: slug,
        title: title.trim(),
        status: currentStatus,
        priority,
        owner_model: model,
        notes,
        source_file: `tasks/${slug}-tasks.md`,
      })
    }
  }
  return tasks
}

function parseAllFiles() {
  const files    = readdirSync(tasksDir).filter(f => f.endsWith('-tasks.md'))
  const allTasks = []
  for (const f of files) {
    allTasks.push(...parseTaskFile(path.join(tasksDir, f)))
  }
  return allTasks
}

// === DB READ ===
function getDbTasks() {
  return db.prepare(
    'SELECT id, project_id, title, status, priority, owner_model, notes, source_file FROM tasks_v2 ORDER BY id'
  ).all()
}

// === HASH (taskflow-012: include notes field) ===
function hashTasks(tasks) {
  const sorted = [...tasks].sort((a, b) => a.id.localeCompare(b.id))
  const data   = sorted
    .map(t => `${t.id}|${t.status}|${t.priority}|${t.owner_model || ''}|${t.title}|${t.notes || ''}`)
    .join('\n')
  return createHash('sha256').update(data).digest('hex').slice(0, 16)
}

// === DIFF ===
function diffTasks(fileTasks, dbTasks) {
  const fileMap = new Map(fileTasks.map(t => [t.id, t]))
  const dbMap   = new Map(dbTasks.map(t => [t.id, t]))
  const diffs   = []

  for (const [id, ft] of fileMap) {
    const dt = dbMap.get(id)
    if (!dt) {
      diffs.push({ type: 'file_only', id, task: ft })
    } else {
      const changes = []
      if (ft.status !== dt.status) changes.push(`status: ${dt.status} → ${ft.status}`)
      if (ft.priority !== dt.priority) changes.push(`priority: ${dt.priority} → ${ft.priority}`)
      if ((ft.owner_model || null) !== (dt.owner_model || null)) changes.push(`model: ${dt.owner_model} → ${ft.owner_model}`)
      if (ft.title !== dt.title) changes.push('title changed')
      if (changes.length) diffs.push({ type: 'changed', id, changes, fileTask: ft, dbTask: dt })
    }
  }

  for (const [id] of dbMap) {
    if (!fileMap.has(id)) {
      diffs.push({ type: 'db_only', id, task: dbMap.get(id) })
    }
  }

  return diffs
}

// === WRITE TO DB ===
function syncFilesToDb(fileTasks, dbTasks, diffs) {
  // Auto-create projects referenced in files but missing from the projects table.
  const knownProjects  = new Set(db.prepare('SELECT id FROM projects').all().map(r => r.id))
  const upsertProject  = db.prepare(`
    INSERT OR IGNORE INTO projects (id, name, description, status, source_file)
    VALUES (?, ?, '', 'active', ?)
  `)
  const missingProjects = new Set()

  for (const t of fileTasks) {
    if (!knownProjects.has(t.project_id) && !missingProjects.has(t.project_id)) {
      missingProjects.add(t.project_id)
      const name = t.project_id.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase())
      upsertProject.run(t.project_id, name, `tasks/${t.project_id}-tasks.md`)
      console.log(`  Auto-created missing project: ${t.project_id} ("${name}")`)
    }
  }

  const upsert = db.prepare(`
    INSERT INTO tasks_v2 (id, project_id, title, status, priority, owner_model, notes, source_file, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, strftime('%Y-%m-%dT%H:%M:%fZ','now'))
    ON CONFLICT(id) DO UPDATE SET
      title       = excluded.title,
      status      = excluded.status,
      priority    = excluded.priority,
      owner_model = excluded.owner_model,
      notes       = COALESCE(excluded.notes, tasks_v2.notes),
      source_file = excluded.source_file,
      updated_at  = strftime('%Y-%m-%dT%H:%M:%fZ','now')
  `)
  const insertTransition = db.prepare(`
    INSERT INTO task_transitions_v2 (task_id, from_status, to_status, reason, actor)
    VALUES (?, ?, ?, ?, 'sync')
  `)

  let updated = 0, added = 0

  for (const diff of diffs) {
    if (diff.type === 'file_only') {
      const t = diff.task
      upsert.run(t.id, t.project_id, t.title, t.status, t.priority, t.owner_model, t.notes, t.source_file)
      insertTransition.run(t.id, null, t.status, 'added via file sync')
      added++
    } else if (diff.type === 'changed') {
      const t = diff.fileTask
      upsert.run(t.id, t.project_id, t.title, t.status, t.priority, t.owner_model, t.notes, t.source_file)
      if (diff.dbTask.status !== t.status) {
        insertTransition.run(t.id, diff.dbTask.status, t.status, `file sync: ${diff.changes.join(', ')}`)
      }
      updated++
    }
    // db_only tasks stay in DB (no silent drops)
  }

  // Update hashes
  const allFileTasks = parseAllFiles()
  const allDbTasks   = getDbTasks()
  db.prepare('UPDATE sync_state SET files_hash = ?, db_hash = ? WHERE id = 1').run(
    hashTasks(allFileTasks), hashTasks(allDbTasks)
  )

  return { added, updated, dbOnly: diffs.filter(d => d.type === 'db_only').length }
}

// === WRITE TO FILES (taskflow-003: blocked is first-class) ===
const STATUS_ORDER = ['in_progress', 'pending_validation', 'blocked', 'backlog', 'done']
const STATUS_HEADERS = {
  in_progress:        'In Progress',
  pending_validation: 'Pending Validation',
  blocked:            'Blocked',
  backlog:            'Backlog',
  done:               'Done',
}

function projectDbToFiles(dbTasks) {
  const byProject = new Map()
  for (const t of dbTasks) {
    if (!byProject.has(t.project_id)) byProject.set(t.project_id, [])
    byProject.get(t.project_id).push(t)
  }

  // Preserve existing file headers (everything before the first ## section)
  const files   = readdirSync(tasksDir).filter(f => f.endsWith('-tasks.md'))
  const headers = new Map()
  for (const f of files) {
    const content = readFileSync(path.join(tasksDir, f), 'utf8')
    const slug    = f.replace(/-tasks\.md$/, '')
    const lines   = content.split(/\r?\n/)
    const headerLines = []
    for (const line of lines) {
      if (line.startsWith('## ')) break
      headerLines.push(line)
    }
    headers.set(slug, headerLines.join('\n').trimEnd())
  }

  // All project slugs from DB
  const slugs = db.prepare('SELECT id FROM projects ORDER BY id').all().map(r => r.id)
  let filesWritten = 0

  for (const slug of slugs) {
    const tasks  = byProject.get(slug) || []
    const header = headers.get(slug) || `# Tasks: ${slug}`

    let md = header + '\n\n'
    for (const section of STATUS_ORDER) {
      md += `## ${STATUS_HEADERS[section]}\n`
      const sectionTasks = tasks
        .filter(t => t.status === section)
        .sort((a, b) => a.priority.localeCompare(b.priority) || a.id.localeCompare(b.id))

      if (sectionTasks.length === 0) {
        md += '\n'
      } else {
        for (const t of sectionTasks) {
          const checkbox = t.status === 'done' ? '[x]' : '[ ]'
          const modelTag = t.owner_model ? ` [${t.owner_model}]` : ''
          md += `- ${checkbox} (task:${t.id}) [${t.priority}]${modelTag} ${t.title}\n`
          if (t.notes) md += `  - note: ${t.notes}\n`
        }
        md += '\n'
      }
    }

    writeFileSync(path.join(tasksDir, `${slug}-tasks.md`), md)
    filesWritten++
  }

  return { filesWritten }
}

// === MAIN ===
try {
  if (mode !== 'check') acquireLock()

  const fileTasks = parseAllFiles()
  const dbTasks   = getDbTasks()
  const diffs     = diffTasks(fileTasks, dbTasks)

  if (mode === 'check') {
    const fileHash = hashTasks(fileTasks)
    const dbHash   = hashTasks(dbTasks)
    if (diffs.length === 0) {
      console.log(`OK: ${fileTasks.length} tasks in sync (hash: ${fileHash})`)
      process.exit(0)
    } else {
      console.log(`DRIFT DETECTED: ${diffs.length} differences`)
      console.log(`  File hash: ${fileHash}`)
      console.log(`  DB hash:   ${dbHash}`)
      for (const d of diffs) {
        if (d.type === 'file_only')  console.log(`  + ${d.id} (in files, not DB)`)
        else if (d.type === 'db_only') console.log(`  - ${d.id} (in DB, not files)`)
        else console.log(`  ~ ${d.id}: ${d.changes.join(', ')}`)
      }
      process.exit(1)
    }
  } else if (mode === 'files-to-db') {
    const result = syncFilesToDb(fileTasks, dbTasks, diffs)
    console.log(`Synced files → DB: ${result.added} added, ${result.updated} updated, ${result.dbOnly} DB-only preserved`)
    releaseLock('ok')
  } else if (mode === 'db-to-files') {
    const freshDbTasks = getDbTasks()
    const result       = projectDbToFiles(freshDbTasks)
    console.log(`Projected DB → files: ${result.filesWritten} files written`)
    releaseLock('ok')
  }
} catch (err) {
  if (mode !== 'check') {
    try { releaseLock(`failed: ${err.message}`) } catch (_) {}
  }
  console.error(err)
  process.exit(1)
}

#!/usr/bin/env node
/**
 * taskflow — CLI entry point (taskflow-011)
 *
 * Commands:
 *   taskflow setup               Interactive first-run onboarding
 *   taskflow status              Pretty terminal summary (all projects)
 *   taskflow export              JSON export to stdout
 *   taskflow sync <mode>         Sync markdown ↔ SQLite (modes: files-to-db | db-to-files | check)
 *   taskflow init                Bootstrap SQLite schema
 *   taskflow install-daemon      Install periodic-sync daemon (LaunchAgent on macOS, systemd on Linux)
 *   taskflow add <project> <title> Create a new task in markdown (source of truth)
 *   taskflow list <project>      List tasks for a project (current tasks by default)
 *   taskflow help                Show this help
 */

import { DatabaseSync } from 'node:sqlite'
import { existsSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const SCRIPTS = path.resolve(__dirname, '..', 'scripts')

// Workspace / DB resolution
const workspace = process.env.OPENCLAW_WORKSPACE || process.cwd()
const dbPath    = path.join(workspace, 'memory', 'taskflow.sqlite')

// ── Colour / terminal helpers ─────────────────────────────────────────────
const isTTY = process.stdout.isTTY
const c = {
  reset:  isTTY ? '\x1b[0m'  : '',
  bold:   isTTY ? '\x1b[1m'  : '',
  dim:    isTTY ? '\x1b[2m'  : '',
  green:  isTTY ? '\x1b[32m' : '',
  yellow: isTTY ? '\x1b[33m' : '',
  blue:   isTTY ? '\x1b[34m' : '',
  cyan:   isTTY ? '\x1b[36m' : '',
  red:    isTTY ? '\x1b[31m' : '',
  gray:   isTTY ? '\x1b[90m' : '',
}

function badge(text, color) {
  return `${color}${text}${c.reset}`
}

// Unicode block progress bar  ▏▎▍▌▋▊▉█
const BLOCKS = ' ▏▎▍▌▋▊▉█'

function progressBar(pct, width = 20) {
  const filled   = Math.round((pct / 100) * width * 8)
  const fullBlks = Math.floor(filled / 8)
  const partial  = filled % 8
  const empty    = width - fullBlks - (partial > 0 ? 1 : 0)

  return (
    '█'.repeat(fullBlks) +
    (partial > 0 ? BLOCKS[partial] : '') +
    '░'.repeat(Math.max(0, empty))
  )
}

function statusColor(status) {
  switch (status) {
    case 'active':  return c.green
    case 'paused':  return c.yellow
    case 'done':    return c.gray
    default:        return c.reset
  }
}

// ── Commands ──────────────────────────────────────────────────────────────

// --- status ------------------------------------------------------------------
function cmdStatus() {
  if (!existsSync(dbPath)) {
    console.error(`${c.red}✗${c.reset} DB not found at: ${dbPath}`)
    console.error(`  Run ${c.bold}taskflow setup${c.reset} to get started, or ${c.bold}taskflow init${c.reset} to bootstrap the database.`)
    process.exit(1)
  }

  const db = new DatabaseSync(dbPath)
  db.exec('PRAGMA foreign_keys = ON')

  const projects = db
    .prepare('SELECT id, name, description, status FROM projects ORDER BY id')
    .all()

  if (projects.length === 0) {
    console.log(`${c.dim}No projects found. Add entries to PROJECTS.md and run: taskflow sync files-to-db${c.reset}`)
    return
  }

  const countRows = db
    .prepare('SELECT project_id, status, COUNT(*) AS cnt FROM tasks_v2 GROUP BY project_id, status')
    .all()

  const countsByProject = {}
  for (const row of countRows) {
    if (!countsByProject[row.project_id]) countsByProject[row.project_id] = {}
    countsByProject[row.project_id][row.status] = row.cnt
  }

  console.log()
  console.log(`${c.bold}${c.cyan}  TaskFlow — Project Overview${c.reset}`)
  console.log(`${c.gray}  ${'─'.repeat(60)}${c.reset}`)

  for (const p of projects) {
    const counts = countsByProject[p.id] || {}
    const ip  = counts.in_progress        ?? 0
    const pv  = counts.pending_validation ?? 0
    const bl  = counts.backlog            ?? 0
    const bk  = counts.blocked            ?? 0
    const dn  = counts.done               ?? 0
    const tot = ip + pv + bl + bk + dn
    const pct = tot > 0 ? Math.round((dn / tot) * 10000) / 100 : 0

    const statusStr = badge(` ${p.status} `, statusColor(p.status))

    console.log()
    console.log(`  ${c.bold}${p.name}${c.reset}  ${statusStr}  ${c.gray}(${p.id})${c.reset}`)
    if (p.description) {
      console.log(`  ${c.dim}${p.description}${c.reset}`)
    }

    // Progress bar
    const bar     = progressBar(pct, 24)
    const pctStr  = pct.toFixed(1).padStart(5)
    console.log(`  ${c.green}${bar}${c.reset}  ${c.bold}${pctStr}%${c.reset} done  ${c.gray}(${tot} tasks)${c.reset}`)

    // Task counts row
    const parts = []
    if (ip)  parts.push(`${c.blue}${ip} in-progress${c.reset}`)
    if (pv)  parts.push(`${c.yellow}${pv} pending-validation${c.reset}`)
    if (bk)  parts.push(`${c.red}${bk} blocked${c.reset}`)
    if (bl)  parts.push(`${c.dim}${bl} backlog${c.reset}`)
    if (dn)  parts.push(`${c.gray}${dn} done${c.reset}`)
    if (parts.length) {
      console.log(`  ${parts.join('  ')}`)
    } else {
      console.log(`  ${c.dim}no tasks yet${c.reset}`)
    }
  }

  console.log()
  console.log(`${c.gray}  ${'─'.repeat(60)}${c.reset}`)
  console.log(`${c.dim}  Workspace: ${workspace}${c.reset}`)
  console.log()
}

// --- export ------------------------------------------------------------------
async function cmdExport() {
  // Import the export script — its top-level code runs and writes JSON to stdout.
  await import(path.join(SCRIPTS, 'export-projects-overview.mjs'))
}

// --- sync --------------------------------------------------------------------
async function cmdSync(mode) {
  const VALID_MODES = ['files-to-db', 'db-to-files', 'check']
  if (!VALID_MODES.includes(mode)) {
    console.error(`${c.red}✗${c.reset} Unknown sync mode: ${JSON.stringify(mode)}`)
    console.error(`  Valid modes: ${VALID_MODES.join(' | ')}`)
    process.exit(1)
  }

  const syncScript = path.join(SCRIPTS, 'task-sync.mjs')
  if (!existsSync(syncScript)) {
    console.error(`${c.red}✗${c.reset} task-sync.mjs not found at: ${syncScript}`)
    process.exit(1)
  }

  // task-sync.mjs reads process.argv[2] for the mode.
  process.argv[2] = mode
  await import(syncScript)
}

// --- init --------------------------------------------------------------------
async function cmdInit() {
  const initScript = path.join(SCRIPTS, 'init-db.mjs')
  if (!existsSync(initScript)) {
    console.error(`${c.red}✗${c.reset} init-db.mjs not found at: ${initScript}`)
    process.exit(1)
  }
  await import(initScript)
}

// --- setup helpers -----------------------------------------------------------

/** Convert a human name to a lowercase-hyphenated slug. */
function toSlug(name) {
  return name
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '')
}

/** Print a summary of what was created and what to do next. */
function printSetupSummary(createdFiles) {
  console.log()
  console.log(`${c.bold}${c.green}  ✓ TaskFlow setup complete!${c.reset}`)
  console.log()
  if (createdFiles.length > 0) {
    console.log(`${c.bold}  Created:${c.reset}`)
    for (const f of createdFiles) {
      console.log(`    ${c.cyan}${f}${c.reset}`)
    }
    console.log()
  }
  console.log(`${c.bold}  Next steps:${c.reset}`)
  console.log(`    ${c.cyan}taskflow status${c.reset}           — view all projects`)
  console.log(`    ${c.cyan}taskflow sync files-to-db${c.reset} — re-sync after editing markdown`)
  console.log(`    ${c.cyan}taskflow help${c.reset}             — full command reference`)
  console.log()
}

/**
 * Offer to install (or describe) the periodic-sync daemon.
 * macOS → LaunchAgent; Linux → systemd user timer.
 *
 * @param {Function|null} ask   - readline ask helper (null when non-interactive)
 * @param {boolean} autoYes     - skip interactive prompt and accept
 */
async function offerLaunchAgent(ask, autoYes = false) {
  const os = process.platform

  if (os === 'linux') {
    console.log()
    console.log(`${c.dim}  Linux detected. Run ${c.cyan}taskflow install-daemon${c.dim} to install the systemd user timer.${c.reset}`)
    return
  }

  if (os !== 'darwin') {
    console.log()
    console.log(`${c.dim}  Platform '${os}' not supported for automatic daemon install.${c.reset}`)
    console.log(`  ${c.gray}Manual cron: * * * * * OPENCLAW_WORKSPACE=${workspace} ${process.execPath} ${path.join(workspace, 'taskflow', 'scripts', 'task-sync.mjs')} files-to-db${c.reset}`)
    return
  }

  // macOS — offer LaunchAgent
  const plistDest = path.join(
    process.env.HOME || '',
    'Library', 'LaunchAgents', 'com.taskflow.sync.plist'
  )

  if (existsSync(plistDest)) {
    console.log(`  ${c.green}✓${c.reset} LaunchAgent already installed at ${plistDest}`)
    return
  }

  const tmplPath = path.join(__dirname, '..', 'system', 'com.taskflow.sync.plist.xml')
  if (!existsSync(tmplPath)) return

  // Non-interactive without --yes: skip LaunchAgent silently
  if (!ask && !autoYes) return

  // Interactive: prompt user
  if (ask && !autoYes) {
    console.log()
    const ans = (await ask('Install LaunchAgent for automatic 60s sync? [Y/n] ')).trim().toLowerCase()
    if (ans === 'n') return
  }

  try {
    const nodeBin = process.execPath
    const plistContent = readFileSync(tmplPath, 'utf8')
      .replace(/\{\{workspace\}\}/g, workspace)
      .replace(/<string>\/usr\/local\/bin\/node<\/string>/, `<string>${nodeBin}</string>`)

    writeFileSync(plistDest, plistContent, 'utf8')
    console.log(`  ${c.green}created${c.reset} ${plistDest}`)

    // Ensure logs dir exists
    const logsDir = path.join(workspace, 'logs')
    if (!existsSync(logsDir)) {
      mkdirSync(logsDir, { recursive: true })
      console.log(`  ${c.green}created${c.reset} logs/`)
    }

    // Load the agent
    const { execSync } = await import('node:child_process')
    try {
      execSync(`launchctl load "${plistDest}"`, { stdio: 'pipe' })
      console.log(`  ${c.green}loaded${c.reset}  com.taskflow.sync LaunchAgent (sync every 60s)`)
    } catch {
      console.log(`  ${c.yellow}!${c.reset} Could not load LaunchAgent automatically. Run manually:`)
      console.log(`    launchctl load "${plistDest}"`)
    }
  } catch (e) {
    console.log(`  ${c.yellow}!${c.reset} LaunchAgent install failed: ${e.message}`)
  }
}

// --- install-daemon ----------------------------------------------------------
/**
 * Detect platform and install the appropriate sync daemon:
 *   macOS  → ~/Library/LaunchAgents/com.taskflow.sync.plist  (launchctl)
 *   Linux  → ~/.config/systemd/user/taskflow-sync.{service,timer}  (systemctl --user)
 */
async function cmdInstallDaemon() {
  const os = process.platform
  const { execSync } = await import('node:child_process')

  console.log()
  console.log(`${c.bold}${c.cyan}  TaskFlow — Install Sync Daemon${c.reset}`)
  console.log(`${c.gray}  ${'─'.repeat(52)}${c.reset}`)
  console.log(`  Platform:  ${c.bold}${os}${c.reset}`)
  console.log(`  Workspace: ${c.bold}${workspace}${c.reset}`)
  console.log()

  // Ensure logs dir exists
  const logsDir = path.join(workspace, 'logs')
  if (!existsSync(logsDir)) {
    mkdirSync(logsDir, { recursive: true })
    console.log(`  ${c.green}created${c.reset} logs/`)
  }

  if (os === 'darwin') {
    // ── macOS: LaunchAgent ───────────────────────────────────────────────
    const plistDest = path.join(process.env.HOME || '', 'Library', 'LaunchAgents', 'com.taskflow.sync.plist')
    const tmplPath  = path.join(__dirname, '..', 'system', 'com.taskflow.sync.plist.xml')

    if (!existsSync(tmplPath)) {
      console.error(`${c.red}✗${c.reset} Template not found: ${tmplPath}`)
      process.exit(1)
    }

    if (existsSync(plistDest)) {
      console.log(`  ${c.green}✓${c.reset} LaunchAgent already installed: ${plistDest}`)
      console.log(`  ${c.dim}To reinstall, unload and remove it first:${c.reset}`)
      console.log(`    launchctl unload "${plistDest}" && rm "${plistDest}"`)
      return
    }

    const nodeBin = process.execPath
    const plistContent = readFileSync(tmplPath, 'utf8')
      .replace(/\{\{workspace\}\}/g, workspace)
      .replace(/\{\{node\}\}/g, nodeBin)

    writeFileSync(plistDest, plistContent, 'utf8')
    console.log(`  ${c.green}created${c.reset}  ${plistDest}`)

    try {
      execSync(`launchctl load "${plistDest}"`, { stdio: 'pipe' })
      console.log(`  ${c.green}loaded${c.reset}   com.taskflow.sync (syncs every 60s)`)
    } catch (e) {
      console.log(`  ${c.yellow}!${c.reset} Could not load automatically. Run:`)
      console.log(`    launchctl load "${plistDest}"`)
    }

    console.log()
    console.log(`  ${c.bold}Verify:${c.reset}  launchctl list | grep taskflow`)
    console.log(`  ${c.bold}Logs:${c.reset}    ${workspace}/logs/taskflow-sync.{stdout,stderr}.log`)

  } else if (os === 'linux') {
    // ── Linux: systemd user timer ────────────────────────────────────────
    const systemdDir  = path.join(process.env.HOME || '', '.config', 'systemd', 'user')
    const svcSrc      = path.join(__dirname, '..', 'system', 'taskflow-sync.service')
    const timerSrc    = path.join(__dirname, '..', 'system', 'taskflow-sync.timer')
    const svcDest     = path.join(systemdDir, 'taskflow-sync.service')
    const timerDest   = path.join(systemdDir, 'taskflow-sync.timer')

    for (const src of [svcSrc, timerSrc]) {
      if (!existsSync(src)) {
        console.error(`${c.red}✗${c.reset} Template not found: ${src}`)
        process.exit(1)
      }
    }

    // Create systemd user dir if needed
    if (!existsSync(systemdDir)) {
      mkdirSync(systemdDir, { recursive: true })
      console.log(`  ${c.green}created${c.reset} ${systemdDir}`)
    }

    const nodeBin = process.execPath

    for (const [src, dest] of [[svcSrc, svcDest], [timerSrc, timerDest]]) {
      const content = readFileSync(src, 'utf8')
        .replace(/\{\{workspace\}\}/g, workspace)
        .replace(/\{\{node\}\}/g, nodeBin)
      writeFileSync(dest, content, 'utf8')
      console.log(`  ${c.green}created${c.reset}  ${dest}`)
    }

    // Reload systemd user daemon and enable+start the timer
    try {
      execSync('systemctl --user daemon-reload', { stdio: 'pipe' })
      console.log(`  ${c.green}reloaded${c.reset} systemd user daemon`)
    } catch {
      console.log(`  ${c.yellow}!${c.reset} daemon-reload failed (is systemd --user running?)`)
    }

    try {
      execSync('systemctl --user enable --now taskflow-sync.timer', { stdio: 'pipe' })
      console.log(`  ${c.green}enabled${c.reset}  taskflow-sync.timer (syncs every 60s)`)
    } catch (e) {
      console.log(`  ${c.yellow}!${c.reset} Could not enable timer automatically. Run:`)
      console.log(`    systemctl --user daemon-reload`)
      console.log(`    systemctl --user enable --now taskflow-sync.timer`)
    }

    console.log()
    console.log(`  ${c.bold}Verify:${c.reset}  systemctl --user status taskflow-sync.timer`)
    console.log(`  ${c.bold}Logs:${c.reset}    journalctl --user -u taskflow-sync.service`)
    console.log(`           ${workspace}/logs/taskflow-sync.{stdout,stderr}.log`)

  } else {
    console.error(`${c.red}✗${c.reset} Platform '${os}' is not supported by install-daemon.`)
    console.error(`  Supported platforms: darwin (macOS), linux`)
    console.error()
    console.error(`  Manual cron fallback:`)
    console.error(`    * * * * * OPENCLAW_WORKSPACE=${workspace} ${process.execPath} ${path.join(workspace, 'taskflow', 'scripts', 'task-sync.mjs')} files-to-db`)
    process.exit(1)
  }

  console.log()
}

/**
 * Offer to set up Apple Notes sync (macOS only).
 * Creates the note via apple-notes-export.mjs and saves the ID to config.
 *
 * @param {Function|null} ask  - readline ask helper
 */
async function offerAppleNotes(ask) {
  if (process.platform !== 'darwin') return

  if (!ask) return   // non-interactive: skip silently

  console.log()
  const ans = (await ask(
    'Set up Apple Notes sync? This creates a shared note that stays updated with your project status. (y/N) '
  )).trim().toLowerCase()

  if (ans !== 'y') return

  const notesScript = path.join(SCRIPTS, 'apple-notes-export.mjs')
  if (!existsSync(notesScript)) {
    console.log(`  ${c.yellow}!${c.reset} apple-notes-export.mjs not found — skipping Notes setup.`)
    return
  }

  console.log()
  console.log(`  ${c.bold}Creating Apple Note…${c.reset}`)
  try {
    await import(notesScript)
    console.log()
    console.log(`  ${c.green}✓${c.reset} Apple Notes sync configured.`)
    console.log(`    Run ${c.cyan}taskflow notes${c.reset} to update manually.`)
    console.log(`    For hourly auto-refresh, add a LaunchAgent or cron:`)
    console.log(`    ${c.gray}0 * * * * OPENCLAW_WORKSPACE=${workspace} ${process.execPath} ${notesScript}${c.reset}`)
  } catch (e) {
    console.log(`  ${c.yellow}!${c.reset} Apple Notes setup failed: ${e.message}`)
    console.log(`    You can retry anytime with: ${c.cyan}taskflow notes${c.reset}`)
  }
}

// --- setup -------------------------------------------------------------------
async function cmdSetup(args) {
  // ── Parse CLI flags (non-interactive mode) ─────────────────────────────
  const nameIdx = args.indexOf('--name')
  const descIdx = args.indexOf('--desc')
  const nonInteractiveName = nameIdx !== -1 ? args[nameIdx + 1] : null
  const nonInteractiveDesc = descIdx !== -1 ? args[descIdx + 1] : null
  const nonInteractive = nonInteractiveName !== null
  const skipLaunchAgent = args.includes('--no-launchagent')
  const autoYes = args.includes('--yes') || args.includes('-y')

  // ── Common paths ────────────────────────────────────────────────────────
  const projectsFile = path.join(workspace, 'PROJECTS.md')
  const tasksDir     = path.join(workspace, 'tasks')
  const plansDir     = path.join(workspace, 'plans')
  const memoryDir    = path.join(workspace, 'memory')

  // ── Readline setup ──────────────────────────────────────────────────────
  let rl  = null
  let ask = null

  if (!nonInteractive) {
    const { createInterface } = await import('node:readline/promises')
    rl = createInterface({ input: process.stdin, output: process.stdout })
    rl.on('SIGINT', () => {
      console.log(`\n\n${c.yellow}Setup interrupted. No changes were committed.${c.reset}\n`)
      rl.close()
      process.exit(0)
    })
    ask = (q) => rl.question(`${c.cyan}?${c.reset} ${q}`)
  }

  const close = () => { if (rl) { rl.close(); rl = null } }

  // ── Header ──────────────────────────────────────────────────────────────
  console.log()
  console.log(`${c.bold}${c.cyan}  TaskFlow Setup${c.reset}`)
  console.log(`${c.gray}  ${'─'.repeat(52)}${c.reset}`)
  console.log(`  Workspace: ${c.bold}${workspace}${c.reset}`)
  console.log()

  // ── Detect current state ────────────────────────────────────────────────
  const hasProjects = existsSync(projectsFile)
  const hasDb       = existsSync(dbPath)

  // ── Scenario 1: Fully set up ────────────────────────────────────────────
  if (hasProjects && hasDb) {
    console.log(`${c.green}✓${c.reset} Already set up — PROJECTS.md and DB both present.`)
    console.log()
    cmdStatus()

    if (!nonInteractive) {
      const ans = await ask('Re-sync markdown → DB now? [y/N] ')
      close()
      if (ans.trim().toLowerCase() === 'y') {
        console.log()
        await cmdSync('files-to-db')
        console.log()
        console.log(`${c.green}✓${c.reset} Sync complete.`)
        console.log()
      }
    }
    return
  }

  // ── Scenario 2: PROJECTS.md exists but no DB ────────────────────────────
  if (hasProjects && !hasDb) {
    console.log(`${c.yellow}!${c.reset} PROJECTS.md found but no SQLite DB.`)

    if (!nonInteractive) {
      const ans = await ask('Initialize DB and sync markdown → DB now? [Y/n] ')
      if (ans.trim().toLowerCase() === 'n') {
        close()
        console.log()
        console.log('Aborted — no changes made.')
        console.log()
        return
      }
    }

    console.log()
    await cmdInit()
    console.log()
    await cmdSync('files-to-db')

    if (!skipLaunchAgent) await offerLaunchAgent(ask, autoYes)
    await offerAppleNotes(ask)
    close()
    printSetupSummary([])
    return
  }

  // ── Scenario 3: Clean slate ──────────────────────────────────────────────
  console.log(`${c.dim}  No existing workspace detected. Starting fresh.${c.reset}`)
  console.log()

  // Create required directories
  const createdFiles = []
  for (const [dir, label] of [[tasksDir, 'tasks/'], [plansDir, 'plans/'], [memoryDir, 'memory/']]) {
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true })
      console.log(`  ${c.green}created${c.reset} ${label}`)
      createdFiles.push(label)
    }
  }

  // Collect project definitions
  const projects = []

  if (nonInteractive) {
    // Non-interactive: single project from flags
    projects.push({ name: nonInteractiveName, desc: nonInteractiveDesc || '' })
  } else {
    // Interactive: first project
    const firstName = (await ask("What's your first project name? ")).trim()
    if (!firstName) {
      close()
      console.log(`\n${c.red}✗${c.reset} Project name is required. Aborting.`)
      console.log()
      process.exit(1)
    }
    const firstDesc = (await ask('One-liner description (optional, press Enter to skip): ')).trim()
    projects.push({ name: firstName, desc: firstDesc })

    // Loop for additional projects
    let addMore = true
    while (addMore) {
      const moreAns = (await ask('Add another project? [y/N] ')).trim().toLowerCase()
      if (moreAns !== 'y') {
        addMore = false
      } else {
        const n = (await ask('  Project name: ')).trim()
        if (n) {
          const d = (await ask('  Description (optional): ')).trim()
          projects.push({ name: n, desc: d })
        }
      }
    }
  }

  // Load tasks template
  const tasksTmplPath = path.join(__dirname, '..', 'templates', 'tasks-template.md')
  let tasksTmpl = null
  try { tasksTmpl = readFileSync(tasksTmplPath, 'utf8') } catch { /* use fallback */ }

  // Build PROJECTS.md content
  let projectsMd = `# Projects\n\n`
  projectsMd += `<!-- ============================================================
  PROJECTS.md — Project Registry
  ============================================================

  FORMAT: One ## block per project. The slug (## heading text)
  is the canonical project ID used in task IDs, file names,
  and SQLite foreign keys. Keep it lowercase and hyphenated.

  FIELDS:
    Name        Human-readable display name (any capitalization).
    Status      One of: active | paused | done
    Description One-sentence summary of the project's purpose.
  ============================================================ -->\n\n`

  for (const p of projects) {
    const slug = toSlug(p.name)

    // Append project block
    projectsMd += `## ${slug}\n- Name: ${p.name}\n- Status: active\n`
    if (p.desc) projectsMd += `- Description: ${p.desc}\n`
    projectsMd += '\n'

    // Create tasks file from template (or fallback)
    const tasksFile = path.join(tasksDir, `${slug}-tasks.md`)
    const tasksContent = tasksTmpl
      ? tasksTmpl
          .replace(/\{\{Project Name\}\}/g, p.name)
          .replace(/\{\{slug\}\}/g, slug)
      : `# ${p.name} — Tasks\n\n## In Progress\n\n## Pending Validation\n\n## Backlog\n\n- [ ] (task:${slug}-001) [P2] First task for this project\n\n## Blocked\n\n## Done\n`

    writeFileSync(tasksFile, tasksContent, 'utf8')
    createdFiles.push(`tasks/${slug}-tasks.md`)
    console.log(`  ${c.green}created${c.reset} tasks/${slug}-tasks.md`)
  }

  // Write PROJECTS.md
  writeFileSync(projectsFile, projectsMd, 'utf8')
  createdFiles.push('PROJECTS.md')
  console.log(`  ${c.green}created${c.reset} PROJECTS.md`)
  console.log()

  // Init DB
  console.log(`${c.bold}  Initializing database…${c.reset}`)
  await cmdInit()
  console.log()

  // Sync files → DB
  console.log(`${c.bold}  Syncing markdown → DB…${c.reset}`)
  await cmdSync('files-to-db')

  // Offer LaunchAgent / cron (interactive only — rl still open)
  if (!skipLaunchAgent) await offerLaunchAgent(ask, autoYes)
  await offerAppleNotes(ask)
  close()

  printSetupSummary(createdFiles)
}


// --- add ---------------------------------------------------------------------
function parseAddArgs(rawArgs) {
  const out = {
    project: null,
    title: null,
    priority: 'P2',
    owner: null,
    status: 'backlog',
    note: null,
    json: false,
    dryRun: false,
    sync: false,
  }

  const rest = [...rawArgs]
  if (!rest.length) return out

  out.project = rest.shift() || null
  if (rest[0] && !rest[0].startsWith('--')) {
    out.title = (rest.shift() || '').trim()
  }

  while (rest.length) {
    const tok = rest.shift()
    if (!tok.startsWith('--')) {
      if (!out.title) out.title = tok.trim()
      else out.title += ` ${tok.trim()}`
      continue
    }

    if (tok === '--priority') out.priority = (rest.shift() || '').trim()
    else if (tok === '--owner') out.owner = (rest.shift() || '').trim()
    else if (tok === '--status') out.status = (rest.shift() || '').trim()
    else if (tok === '--note') out.note = (rest.shift() || '').trim()
    else if (tok === '--json') out.json = true
    else if (tok === '--dry-run') out.dryRun = true
    else if (tok === '--sync') out.sync = true
    else {
      console.error(`${c.red}✗${c.reset} Unknown flag for add: ${tok}`)
      process.exit(1)
    }
  }

  return out
}

function escapeTaskTitle(title) {
  return title.replace(/\s+/g, ' ').trim()
}

function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

async function cmdAdd(rawArgs) {
  const args = parseAddArgs(rawArgs)
  const allowedStatus = ['backlog', 'in_progress', 'pending_validation', 'blocked', 'done']
  const allowedPriority = ['P0', 'P1', 'P2', 'P3', 'P9']
  const sectionByStatus = {
    in_progress: 'In Progress',
    pending_validation: 'Pending Validation',
    backlog: 'Backlog',
    blocked: 'Blocked',
    done: 'Done',
  }

  if (!args.project || !args.title) {
    console.error(`${c.red}✗${c.reset} Usage: taskflow add <project> <title> [--priority P2] [--owner codex] [--status backlog|in_progress|pending_validation|blocked|done] [--note "..."] [--json] [--dry-run] [--sync]`)
    process.exit(1)
  }

  const project = args.project.trim().toLowerCase()
  const title = escapeTaskTitle(args.title)
  const status = args.status.toLowerCase()
  const priority = args.priority.toUpperCase()
  const BANNED_HEADERS = /^(in progress|pending validation|backlog|blocked|done)$/i

  if (!title || BANNED_HEADERS.test(title) || /\r|\n/.test(title)) {
    console.error(`${c.red}✗${c.reset} Invalid task title.`)
    process.exit(1)
  }
  if (!allowedStatus.includes(status)) {
    console.error(`${c.red}✗${c.reset} Invalid --status '${args.status}'. Allowed: ${allowedStatus.join(', ')}`)
    process.exit(1)
  }
  if (!allowedPriority.includes(priority)) {
    console.error(`${c.red}✗${c.reset} Invalid --priority '${args.priority}'. Allowed: ${allowedPriority.join(', ')}`)
    process.exit(1)
  }
  if (args.owner && !/^[A-Za-z0-9._-]{1,64}$/.test(args.owner)) {
    console.error(`${c.red}✗${c.reset} Invalid --owner '${args.owner}'. Use letters, numbers, dot, underscore, dash.`)
    process.exit(1)
  }

  const projectsFile = path.join(workspace, 'PROJECTS.md')
  if (!existsSync(projectsFile)) {
    console.error(`${c.red}✗${c.reset} PROJECTS.md not found at: ${projectsFile}`)
    process.exit(1)
  }
  const projectsText = readFileSync(projectsFile, 'utf8')
  const projectHeader = new RegExp(`^##\\s+${escapeRegex(project)}\\s*$`, 'm')
  if (!projectHeader.test(projectsText)) {
    console.error(`${c.red}✗${c.reset} Unknown project '${project}'. Add it to PROJECTS.md first.`)
    process.exit(1)
  }

  const taskFile = path.join(workspace, 'tasks', `${project}-tasks.md`)
  if (!existsSync(taskFile)) {
    console.error(`${c.red}✗${c.reset} Task file not found: ${taskFile}`)
    process.exit(1)
  }

  const original = readFileSync(taskFile, 'utf8')
  const idRe = new RegExp(`\\(task:${escapeRegex(project)}-(\\d{1,})\\)`, 'g')
  let m
  let maxN = 0
  while ((m = idRe.exec(original)) !== null) {
    const n = Number(m[1])
    if (Number.isFinite(n) && n > maxN) maxN = n
  }
  const nextId = `${project}-${String(maxN + 1).padStart(3, '0')}`

  const sectionHeader = `## ${sectionByStatus[status]}`
  const lines = original.split(/\n/)
  const secIdx = lines.findIndex(l => l.trim() === sectionHeader)
  if (secIdx < 0) {
    console.error(`${c.red}✗${c.reset} Section '${sectionHeader}' not found in ${taskFile}`)
    process.exit(1)
  }

  let insertIdx = lines.length
  for (let i = secIdx + 1; i < lines.length; i++) {
    if (/^##\s+/.test(lines[i])) {
      insertIdx = i
      break
    }
  }

  const checkbox = status === 'done' ? '[x]' : '[ ]'
  let taskLine = `- ${checkbox} (task:${nextId}) [${priority}]`
  if (args.owner) taskLine += ` [${args.owner}]`
  taskLine += ` ${title}`

  const insertion = [taskLine]
  if (args.note) insertion.push(`  - note: ${args.note.replace(/\s+/g, ' ').trim()}`)
  if (insertIdx > 0 && lines[insertIdx - 1] !== '') insertion.unshift('')

  lines.splice(insertIdx, 0, ...insertion)
  const updated = lines.join('\n')

  const payload = {
    id: nextId,
    project,
    title,
    priority,
    status,
    owner: args.owner || null,
    note: args.note || null,
    file: taskFile,
    section: sectionByStatus[status],
    dryRun: args.dryRun,
  }

  if (args.dryRun) {
    if (args.json) console.log(JSON.stringify(payload, null, 2))
    else {
      console.log(`${c.cyan}[dry-run]${c.reset} would create ${c.bold}${nextId}${c.reset} in ${taskFile}`)
      console.log(`  section: ${sectionByStatus[status]}`)
      console.log(`  line: ${taskLine}`)
      if (args.note) console.log(`  note: ${args.note}`)
    }
    return
  }

  writeFileSync(taskFile, updated, 'utf8')
  if (args.sync) await cmdSync('files-to-db')

  if (args.json) console.log(JSON.stringify(payload, null, 2))
  else {
    console.log(`${c.green}✓${c.reset} Added ${c.bold}${nextId}${c.reset} to ${project} (${sectionByStatus[status]}).`)
    console.log(`  ${taskFile}`)
  }
}

// --- list --------------------------------------------------------------------
function parseListArgs(rawArgs) {
  const out = {
    project: null,
    all: false,
    status: null,
    priority: null,
    owner: null,
    json: false,
    limit: null,
  }

  const rest = [...rawArgs]
  if (!rest.length) return out

  if (rest[0] && !rest[0].startsWith('--')) {
    out.project = (rest.shift() || '').trim() || null
  }

  while (rest.length) {
    const tok = rest.shift()
    if (tok === '--all') out.all = true
    else if (tok === '--status') out.status = (rest.shift() || '').trim()
    else if (tok === '--priority') out.priority = (rest.shift() || '').trim()
    else if (tok === '--owner') out.owner = (rest.shift() || '').trim()
    else if (tok === '--project') out.project = (rest.shift() || '').trim() || null
    else if (tok === '--json') out.json = true
    else if (tok === '--limit') {
      const n = Number(rest.shift())
      if (!Number.isFinite(n) || n <= 0) {
        console.error(`${c.red}✗${c.reset} --limit must be a positive number`)
        process.exit(1)
      }
      out.limit = Math.floor(n)
    } else {
      console.error(`${c.red}✗${c.reset} Unknown flag for list: ${tok}`)
      process.exit(1)
    }
  }

  return out
}

function splitCsv(input) {
  return (input || '')
    .split(',')
    .map(s => s.trim())
    .filter(Boolean)
}

function firstNoteLine(notes) {
  if (!notes) return null
  const line = String(notes).split(/\r?\n/).map(s => s.trim()).find(Boolean)
  return line || null
}

function formatTaskLine(task) {
  const owner = task.owner_model ? ` [${task.owner_model}]` : ''
  const note = task.first_note ? `\n    ${c.dim}note:${c.reset} ${task.first_note}` : ''
  return `  - (${task.id}) [${task.priority}]${owner} ${task.title}${note}`
}

function resolveProject(db, projectRef) {
  const raw = (projectRef || '').trim()
  if (!raw) return { project: null }

  const exactId = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(raw.toLowerCase())
  if (exactId) return { project: exactId }

  const all = db.prepare('SELECT id, name FROM projects ORDER BY id').all()
  const ref = raw.toLowerCase()

  const exactName = all.filter(p => String(p.name || '').toLowerCase() === ref)
  if (exactName.length === 1) return { project: exactName[0] }

  const starts = all.filter(p => p.id.toLowerCase().startsWith(ref) || String(p.name || '').toLowerCase().startsWith(ref))
  if (starts.length === 1) return { project: starts[0] }

  const contains = all.filter(p => p.id.toLowerCase().includes(ref) || String(p.name || '').toLowerCase().includes(ref))
  if (contains.length === 1) return { project: contains[0] }

  const candidates = starts.length ? starts : contains
  if (candidates.length > 1) return { project: null, ambiguous: true, candidates }

  return { project: null }
}

function cmdList(rawArgs) {
  const args = parseListArgs(rawArgs)
  const allowedStatus = ['in_progress', 'pending_validation', 'blocked', 'backlog', 'done']
  const allowedPriority = ['P0', 'P1', 'P2', 'P3', 'P9']
  const statusOrder = ['in_progress', 'pending_validation', 'blocked', 'backlog', 'done']
  const statusLabel = {
    in_progress: 'In Progress',
    pending_validation: 'Pending Validation',
    blocked: 'Blocked',
    backlog: 'Backlog',
    done: 'Done',
  }
  const priorityRank = { P0: 0, P1: 1, P2: 2, P3: 3, P9: 4 }

  if (!args.project) {
    console.error(`${c.red}✗${c.reset} Usage: taskflow list <project> [--project <slug|name>] [--all] [--status in_progress,backlog] [--priority P1,P2] [--owner codex] [--json] [--limit N]`)
    process.exit(1)
  }

  if (!existsSync(dbPath)) {
    console.error(`${c.red}✗${c.reset} DB not found at: ${dbPath}`)
    console.error(`  Run ${c.bold}taskflow init${c.reset} and ${c.bold}taskflow sync files-to-db${c.reset} first.`)
    process.exit(1)
  }

  const selectedStatuses = args.status ? splitCsv(args.status).map(s => s.toLowerCase()) : null
  if (selectedStatuses) {
    const invalid = selectedStatuses.filter(s => !allowedStatus.includes(s))
    if (invalid.length) {
      console.error(`${c.red}✗${c.reset} Invalid --status value(s): ${invalid.join(', ')}`)
      console.error(`  Allowed: ${allowedStatus.join(', ')}`)
      process.exit(1)
    }
  }

  const selectedPriorities = args.priority ? splitCsv(args.priority).map(p => p.toUpperCase()) : null
  if (selectedPriorities) {
    const invalid = selectedPriorities.filter(p => !allowedPriority.includes(p))
    if (invalid.length) {
      console.error(`${c.red}✗${c.reset} Invalid --priority value(s): ${invalid.join(', ')}`)
      console.error(`  Allowed: ${allowedPriority.join(', ')}`)
      process.exit(1)
    }
  }

  const db = new DatabaseSync(dbPath)
  db.exec('PRAGMA foreign_keys = ON')

  const resolved = resolveProject(db, args.project)
  if (!resolved.project) {
    if (resolved.ambiguous) {
      console.error(`${c.red}✗${c.reset} Ambiguous project reference '${args.project}'.`)
      console.error(`  Matches: ${resolved.candidates.map(p => `${p.id} (${p.name})`).join(', ')}`)
      process.exit(1)
    }
    console.error(`${c.red}✗${c.reset} Unknown project '${args.project}' in DB.`)
    console.error(`  Run ${c.bold}taskflow sync files-to-db${c.reset} if it exists in PROJECTS.md.`)
    process.exit(1)
  }
  const project = resolved.project

  const rows = db.prepare(`
    SELECT id, project_id, title, status, priority, owner_model, notes
    FROM tasks_v2
    WHERE project_id = ?
  `).all(project.id)

  const defaultStatuses = ['in_progress', 'pending_validation', 'blocked', 'backlog']
  const wantedStatuses = selectedStatuses || (args.all ? [...statusOrder] : defaultStatuses)

  let filtered = rows
    .filter(r => wantedStatuses.includes(r.status))
    .filter(r => !selectedPriorities || selectedPriorities.includes(r.priority))
    .filter(r => !args.owner || (r.owner_model || '').toLowerCase() === args.owner.toLowerCase())
    .map(r => ({ ...r, first_note: firstNoteLine(r.notes) }))

  filtered.sort((a, b) => {
    const s = statusOrder.indexOf(a.status) - statusOrder.indexOf(b.status)
    if (s !== 0) return s
    const p = (priorityRank[a.priority] ?? 999) - (priorityRank[b.priority] ?? 999)
    if (p !== 0) return p
    return a.id.localeCompare(b.id)
  })

  if (args.limit) filtered = filtered.slice(0, args.limit)

  if (args.json) {
    const grouped = {}
    for (const s of statusOrder) grouped[s] = []
    for (const row of filtered) grouped[row.status].push(row)

    console.log(JSON.stringify({
      project: { id: project.id, name: project.name },
      filters: {
        all: args.all,
        status: wantedStatuses,
        priority: selectedPriorities,
        owner: args.owner || null,
        limit: args.limit || null,
      },
      total: filtered.length,
      tasks: filtered,
      grouped,
    }, null, 2))
    return
  }

  console.log()
  console.log(`${c.bold}${project.name}${c.reset} ${c.gray}(${project.id})${c.reset}`)
  console.log(`${c.dim}Showing ${filtered.length} task(s)${c.reset}`)

  if (!filtered.length) {
    console.log(`${c.dim}No matching tasks.${c.reset}`)
    console.log()
    return
  }

  for (const status of statusOrder) {
    const bucket = filtered.filter(r => r.status === status)
    if (!bucket.length) continue
    console.log()
    console.log(`${c.bold}${statusLabel[status]}${c.reset} ${c.gray}(${bucket.length})${c.reset}`)
    for (const task of bucket) console.log(formatTaskLine(task))
  }

  console.log()
}

