async function cmdNotes() {
  const notesScript = path.join(SCRIPTS, 'apple-notes-export.mjs')
  if (!existsSync(notesScript)) {
    console.error(`${c.red}✗${c.reset} apple-notes-export.mjs not found at: ${notesScript}`)
