// ── Dispatch ─────────────────────────────────────────────────────────────
const [,, cmd, ...args] = process.argv

switch (cmd) {
  case 'setup':
    await cmdSetup(args)
    break

  case 'status':
    cmdStatus()
    break

  case 'export':
    await cmdExport()
    break

  case 'sync':
    await cmdSync(args[0] || 'check')
    break

  case 'init':
    await cmdInit()
    break

  case 'install-daemon':
    await cmdInstallDaemon()
    break

  case 'add':
    cmdAdd(args)
    break

  case 'list':
    cmdList(args)
    break

  case 'notes':
    await cmdNotes()
    break

  case 'help':
  case '--help':
  case '-h':
    cmdHelp()
    break

  case undefined:
    // No args: show status as a sensible default
    cmdStatus()
    break

  default:
    console.error(`${c.red}✗${c.reset} Unknown command: ${JSON.stringify(cmd)}`)
    console.error(`  Run ${c.bold}taskflow help${c.reset} for usage.`)
    process.exit(1)
}
